UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Yunan Souvlakisi ve Tzatziki'), description_tr = COALESCE(description_tr, 'Akdeniz diyetinin gözdesi: Saf protein, probiyotikler ve sağlıklı yağlar.

