UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Keten Tohumlu ve Chialı Puding'), description_tr = COALESCE(description_tr, 'Hazırlaması 2 dakika süren, kahvaltı veya ara öğün için sindirim dostu ve tok tutan bir puding.

