UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Smoothie Kasesi(4 yaş+)'), description_tr = COALESCE(description_tr, 'Sebze ve meyveleri sıvı hâlde sevdiren, kaşıkla yenen eğlenceli bir tatlı.

