UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Toskana Güneşi'), description_tr = COALESCE(description_tr, 'İtalya''nın ünlü "Melanzane alla Parmigiana" yemeğinin kızartılmadan hazırlanan, hafif ve sağlıklı versiyonu.

