UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Narlı Yoğurt Barı'), description_tr = COALESCE(description_tr, 'Göz kamaştıran bir dondurma alternatifi. Serinletici ve aynı zamanda çıtır.

