UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Doldurulmuş Portobello Mantarı'), description_tr = COALESCE(description_tr, 'Kırmızı et tüketmeden et dokusu ve lezzeti sunan harika "şapkalar".

