UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Gold Mac & Cheese (2 yaş+)'), description_tr = COALESCE(description_tr, 'Çocukların en sevdiği peynirli makarnanın içine sebzelerin gizlendiği çok sağlıklı bir versiyon.

