UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Matcha Strawberry Cloud'), description_tr = COALESCE(description_tr, 'Sosyal medyanın en trend içeceği. Cildi besleyen bir antioksidan bombası.'), category_tr = COALESCE(category_tr, 'Sağlıklı içecekler'), tags_tr = COALESCE(tags_tr, ARRAY['general']::text[]), ingredients_tr = COALESCE(ingredients_tr, '["1 çay kaşığı matcha tozu (ılık suda çözülmüş), 4-5 adet taze çilek (ezilerek püre haline getirilmiş), 1 su bardağı badem sütü, buz."]'::jsonb), instructions_tr = COALESCE(instructions_tr, '["Bardağın dibine çilek püresini koyun, üzerine buzları ve sütü ekleyin. Son olarak çözülmüş yeşil matchayı, renkler katmanlar hâlinde (altta pembe, üstte yeşil) kalacak şekilde yavaşça dökün."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
