UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'İskandinav Smørrebrød'), description_tr = COALESCE(description_tr, 'Danimarka ve Norveç''e özgü, koyu renkli çavdar ekmeği üzerinde hazırlanan açık sandviç sanatı.

