UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Brokoli ve Dana Eti Sote'), description_tr = COALESCE(description_tr, 'Ünlü Asya (Çin) mutfağının tüm dünyada sevilen en sağlıklı klasiklerinden biri.

