UPDATE public.admin_recipes SET title_tr = COALESCE(title_tr, 'Nohutlu Blondie'), description_tr = COALESCE(description_tr, 'İçinde nohut olduğuna kimsenin inanmayacağı, karamelli ve unsuz bir kek.

Faydası: Bu tatlı saf protein ve kompleks karbonhidrat kaynağıdır. Glütene bağlı şişkinliğe yol açmaz ve akşam egzersizinden sonra (kasların toparlanması için) çayın yanında harika gider.'), category_tr = COALESCE(category_tr, 'Sağlıklı tatlılar'), tags_tr = COALESCE(tags_tr, ARRAY['genel']::text[]), ingredients_tr = COALESCE(ingredients_tr, '["Konserve nohut: 1 su bardağı (iyice yıkanmış ve kabukları soyulmuş)","Fıstık ezmesi: 3 yemek kaşığı","Bal veya akçaağaç şurubu: 3 yemek kaşığı","Vanilya, kabartma tozu.","Damla çikolata (bitter)."]'::jsonb), instructions_tr = COALESCE(instructions_tr, '["Çikolata dışındaki tüm malzemeleri blenderda tamamen pürüzsüz (hamur kıvamında) olana kadar çekin. Damla çikolatayı ekleyip küçük, kare bir kek kalıbına dökün. 175 derecede 20 dk. pişirin. Ilıkken dilimleyin."]'::jsonb) WHERE id = '4b5bc08b-15b1-4187-aa19-05b7b3bb4ae4';

