UPDATE public.safety_items SET name_tr = COALESCE(name_tr, 'Uçuş'), description_tr = COALESCE(description_tr, 'Ticari hava yolu şirketleriyle yapılan uçuşlar genel olarak hamilelik döneminde güvenli kabul edilir. Ancak özellikle uzun süreli uçuşlardan önce, hamilelikle ilgili herhangi bir sorununız olmasa bile doktorunuza danışmanız önerilir. Bol su için, kan pıhtılaşmasını önlemek için hareket edin ve önerilirse kompresyon çorabı kullanın. Bu öneriler emziren anneler için de geçerlidir; ancak uzun uçuşlarda bebeğin beslenmesi ve konforu için ek hazırlık yapmak faydalı olabilir.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
