UPDATE public.safety_items SET name_tr = COALESCE(name_tr, 'Uçmak'), description_tr = COALESCE(description_tr, 'Ticari uçuşlar genel olarak hamilelik döneminde güvenli kabul edilir. Özellikle üçüncü trimesterde uçuş konusunda doktorunuza danışmanız; kan pıhtılaşmasını önlemek için bol su içmeniz ve hareket etmeniz önerilir. Bu öneriler emziren anneler için de geçerlidir; ancak uzun uçuşlarda bebeğin beslenmesi ve konforu için ek hazırlık yapmak gerekir.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
